#include <iostream>

using namespace std;

struct Point {
    long long x, y;
};

// Vector subtraction: B - A
Point vec(Point A, Point B) {
    return {B.x - A.x, B.y - A.y};
}

// Dot product of two vectors
long long dot(Point A, Point B) {
    return A.x * B.x + A.y * B.y;
}

// 2D Cross product of two vectors (A x B)
long long cross(Point A, Point B) {
    return A.x * B.y - A.y * B.x;
}

// Squared distance between two points
long long distSq(Point A, Point B) {
    long long dx = A.x - B.x;
    long long dy = A.y - B.y;
    return dx * dx + dy * dy;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Point P[8];
    for (int i = 1; i <= 7; ++i) {
        if (!(cin >> P[i].x >> P[i].y)) return 0;
    }

    // Condition 1: Angle P2-P1-P3 is acute (vertex at P1)
    // u = P2 - P1, v = P3 - P1. Dot product must be strictly positive.
    Point u = vec(P[1], P[2]);
    Point v = vec(P[1], P[3]);
    if (dot(u, v) <= 0) {
        cout << "N\n";
        return 0;
    }

    // Condition 2: Segments P1P2 and P1P3 have the same length
    if (distSq(P[1], P[2]) != distSq(P[1], P[3])) {
        cout << "N\n";
        return 0;
    }

    // Condition 3: Points P2, P3, P4, and P5 are collinear
    Point base = vec(P[2], P[3]);
    if (cross(base, vec(P[2], P[4])) != 0 || cross(base, vec(P[2], P[5])) != 0) {
        cout << "N\n";
        return 0;
    }

    // Condition 4: Midpoints of P2P3 and P4P5 coincide
    // (P2 + P3) == (P4 + P5)
    if (P[2].x + P[3].x != P[4].x + P[5].x || P[2].y + P[3].y != P[4].y + P[5].y) {
        cout << "N\n";
        return 0;
    }

    // Condition 5: Segment P2P3 is strictly longer than P4P5
    if (distSq(P[2], P[3]) <= distSq(P[4], P[5])) {
        cout << "N\n";
        return 0;
    }

    // Condition 6: P4P6 and P5P7 are perpendicular to P2P3
    Point v46 = vec(P[4], P[6]);
    Point v57 = vec(P[5], P[7]);
    if (dot(v46, base) != 0 || dot(v57, base) != 0) {
        cout << "N\n";
        return 0;
    }

    // Condition 7: Segments P4P6 and P5P7 have the same length
    if (distSq(P[4], P[6]) != distSq(P[5], P[7])) {
        cout << "N\n";
        return 0;
    }

    // Condition 8: P1 and P6 are separated by the line containing P2P3
    // Formally, the cross products of (P3 - P2) with (P1 - P2) and (P6 - P2) have opposite signs
    long long cp1 = cross(base, vec(P[2], P[1]));
    long long cp6 = cross(base, vec(P[2], P[6]));
    if (!((cp1 > 0 && cp6 < 0) || (cp1 < 0 && cp6 > 0))) {
        cout << "N\n";
        return 0;
    }

    cout << "S\n";
    return 0;
}
